def _parse_field(field):
    """Parse one raw field (no unquoted SEP); return (key, value) or None if blank."""
    if "=" not in field:
        if not field.strip():
            return None
        raise ValueError(f"field without '=': {field!r}")
    key, rest = field.split("=", 1)
    key = key.strip()
    if not key:
        raise ValueError(f"empty key in {field!r}")
    rest = rest.lstrip()
    if rest.startswith(QUOTE):
        value, i, n = "", 1, len(rest)
        while True:
            if i >= n:
                raise ValueError(f"unclosed quote in {field!r}")
            ch = rest[i]
            if ch == QUOTE:
                if i + 1 < n and rest[i + 1] == QUOTE:
                    value += QUOTE
                    i += 2
                    continue
                i += 1
                break
            value += ch
            i += 1
        if rest[i:].strip():
            raise ValueError(f"text after closing quote in {field!r}")
        return key, value
    return key, rest.strip()


def parse_fields(text):
    """Parse a line like name=Ann| note='hi| there' into a dict of strings.

    Fields are separated by SEP. Whitespace around keys and around unquoted values is
    ignored. A value may be wrapped in QUOTE characters; inside quotes, SEP and '='
    are ordinary characters, whitespace is kept, and two QUOTE characters in a row
    stand for one QUOTE character. Empty fields, such as one after a trailing SEP,
    are skipped, so a blank line gives {}. A field without '=', an empty key, a
    quote that is never closed, or a key that appears twice raises ValueError.
    """
    # Split on SEP, ignoring SEPs inside a quoted value (one that opens right
    # after '=' and optional whitespace).
    fields, field = [], ""
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch == SEP:
            fields.append(field)
            field = ""
            i += 1
        elif ch == "=" and "=" not in field:
            field += ch
            i += 1
            j = i
            while j < n and text[j].isspace():
                j += 1
            if j < n and text[j] == QUOTE:
                k = j + 1
                while True:
                    if k >= n:
                        raise ValueError("unclosed quote")
                    if text[k] == QUOTE:
                        if k + 1 < n and text[k + 1] == QUOTE:
                            k += 2
                            continue
                        break
                    k += 1
                field += text[i:k + 1]
                i = k + 1

        else:
            field += ch
            i += 1
    fields.append(field)
    result = {}
    for raw in fields:
        parsed = _parse_field(raw)
        if parsed is None:
            continue
        key, value = parsed
        if key in result:
            raise ValueError(f"duplicate key {key!r}")
        result[key] = value
    return result
